INSERT INTO dump_descriptions (base_key, description) VALUES ('ac_rework', 'Rebalances the Autocannon toward stronger area damage and kill power, with revised upgrades and overclocks intended to compete with the Minigun and Hurricane.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('arcadecorerez', 'Reskins Radioactive Exclusion Zone materials and props in an arcadecore style; version notes mention purple uranium crystals and an animated plant material.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('brt_overhaul', 'Reworks the BRT7 Burst Fire Pistol into a close-range, shotgun-style secondary, with redesigned upgrades, overclocks, and firing behavior.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('build-inspector-with-names', 'Edits Build Inspector so player names appear whenever there is more than one player, making same-class teammates easier to distinguish.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('enemyculllpeonlytrash', 'Culls only low-priority trash enemies and bundles Low Poly Enemies assets; this is a fork of Enemy Cull.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('mev_s5_stalker', 'Adds the beta Stalker enemy descriptor to MEV so encounter settings can spawn it; load this pak above MEV.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('newocparticleremoves', 'Provides separate particle-removal paks for Cluster Charges, Combustive Goo Mix, and Mortar Rounds, plus one pak that removes all three.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('no_season_event_waves', 'Stops Pool Floats and Oktoberfest mugs from triggering enemy waves; the host must run it for the change to affect the lobby.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('noc4collision', 'Prevents projectiles from intercepting C4; this host-side change applies to the whole lobby.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('noragdoll-grabberfix', 'Fixes Grabber behavior in no-ragdoll setups by preventing Grabber ragdolls; it does not require a separate ragdoll mod.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('noragdoll-grabberfix(praetopp)', 'Prevents Grabber ragdolls while retaining Praetorian and Oppressor ragdolls, so their gas-spawn positions remain visible.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('nwos_alldirections', 'Extends No Walk Only Sprint so autosprint works with W/A/S/D at the same speed in every direction; vanilla slowdowns still apply. Client-side and replaces the original NWOS pak.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
